    assert(std::abs(probabilityOnTime(3, 4, 1, 3) - 1.0) < 1e-12); // x<=a -> 1.0
    assert(std::abs(probabilityOnTime(3, 4, 1, 4) - 1.0) < 1e-12); // x==b -> 1/(4-3)=1.0
    assert(std::abs(probabilityOnTime(3, 4, 0, 4) - 0.0) < 1e-12); // c=0 at b -> 0/(1)=0.0
    return 0;
}

