    assert(maximumTotalCost({-1, -2, -3}) == -2); // Best: [-1,-2] and [-3]? [-1,-2] = -1 -(-2)=1, plus [-3] = -2? Wait compute: [-1,-2][-3] = ( -1 -(-2) ) + (-3) = 1 -3 = -2; [-1][-2,-3] = -1 + (-2 -(-3)) = -1 + 1 = 0; [-1,-2,-3] = -1 -(-2) -(-3)= -1+2+3=4. So max=4. So assert should be 4.

