#include <bits/stdc++.h>

using namespace std;

struct Item {
    int index;
    int val;

    Item(int index, int val) : index(index), val(val) {};
};

int largestRectangleArea(vector<int> &heights) {
    stack<Item *> s;
    s.push(new Item(-1, -1));
    int MAX = 0;
    for (int i = 0; i < heights.size(); i++) {
        if (heights[i] < s.top()->val) {
            while (s.top()->val > heights[i]) {
                Item *top = s.top();
                s.pop();

                MAX = max(MAX, top->val * (i - s.top()->index - 1));
            }
        }
        s.push(new Item(i, heights[i]));
    }
    Item *last = nullptr;
    while (!s.empty()) {
        if (last == nullptr) {
            last = s.top();
            s.pop();
            MAX = max(MAX, last->val);
            continue;
        }
        Item *top = s.top();
        MAX = max(MAX, ((int) heights.size() - 1 - top->index) * last->val);
        last = top;
        s.pop();
    }
    return MAX;
}

