    diff = (S - R) & 0x3f;

    tmask_and = (diff | ~levels) & 0x3f;
    tmask_or  = (diff & levels) & 0x3f;

    tmask = 0xffffffffffffffffULL;

    for (int i = 0; i < 6; ++i) {
        int nbits = 1 << i;
