                 | replicate(or_bits_top, 2 * nbits, 32 / nbits));
    }

    wmask_and = (immr | ~levels) & 0x3f;
    wmask_or  = (immr & levels) & 0x3f;

    wmask = 0;

    for (int i = 0; i < 6; ++i) {
