                len2 = i;
                break;
            }
        }
        if (len2 >= len) return 0;
    }

    levels = (1U << len) - 1;

    if ((imms & levels) == levels) return 0;

    S = imms & levels;
    R = immr & levels;

    // 6‑bit arithmetic: diff = S - R (mod 64)
    diff = (S - R) & 0x3f;

    tmask_and = (diff | ~levels) & 0x3f;
    tmask_or  = (diff & levels) & 0x3f;

    tmask = 0xffffffffffffffffULL;

