        };
        auto result = mergeSwitchRanges(input);
        assert(result.size() == 2);
        assert(result[0].lo == 1 && result[0].hi == 20 && result[0].dest == 100);
        assert(std::abs(result[0].cnt - 8.0) < 1e-9);
