        };
        auto result = mergeSwitchRanges(input);
        assert(result.size() == 2);
        assert(result[0].dest == -1);
        assert(result[1].dest == 9);
    }

    // Case 5: Non-contiguous ranges should never merge.
    {
        std::vector<SwitchRange> input = {
            {1, 5, 3, 1.0},
            {7, 10, 3, 1.0}
        };
        auto result = mergeSwitchRanges(input);
        assert(result.size() == 2);
    }

    // Case 6: Empty input.
    {
        std::vector<SwitchRange> input = {};
