            long long pairSum = v[i] + v[i + 1];
            gain[i] = std::max(gain[i], pairProd - pairSum);
        }
        if (i + 2 < n) {
            long long tripleProd = v[i] * v[i + 1] * v[i + 2];
            long long tripleSum = v[i] + v[i + 1] + v[i + 2];
            gain[i] = std::max(gain[i], tripleProd - tripleSum);
        }
    }

