class Solution {
public:
    // 合并两个链表，problem-21.cpp
    ListNode *mergeTwoLists(ListNode *l1, ListNode *l2) {
        ListNode ret;
        ListNode *node = &ret;
        while (l1 != nullptr && l2 != nullptr) {
            if (l1->val < l2->val) {
                node->next = l1;
                l1 = l1->next;
            } else {
                node->next = l2;
                l2 = l2->next;
            }
            node = node->next;
        }
        node->next = l1 ? l1 : l2;
        return ret.next;
    }

