    v.pop_back();
    cout << "Element removed" << endl;
    cout << "Size : " << v.size() << endl;

    //we can also access or change elements of vector just like the arrays

    cout << "3rd element is " << v[3] << endl;
    v[3] = 122;
    cout << "Now 3rd element is " << v[3] << endl;

