    if (data.empty()) {
        return {0, 0, 0};
    }

    int minVal = data[0];
    int maxVal = data[0];
    int sum = 0;

    for (const int value : data) {
        minVal = std::min(minVal, value);
        maxVal = std::max(maxVal, value);
        sum += value;
    }

    return {minVal, maxVal, sum};
}
