    while (idx < length) {
        longer[idx] += carry;          // Add carry to current digit
        carry = (longer[idx] - '0') / 2;   // New carry (0 or 1 since binary)
        longer[idx] = (longer[idx] - '0') % 2 + '0'; // Set digit to 0 or 1
