int64_t smallestNumberWithForbidden(uint64_t L, uint64_t R, const vector<string>& patterns) {
    if (L > R) return -1;
    // Binary search for smallest T such that countUpTo(T) - countUpTo(L-1) >= 1
    uint64_t lo = L, hi = R;
    while (lo < hi) {
        uint64_t mid = lo + (hi - lo) / 2;
