    uint64_t leftCount = (lo == 0 ? 0 : countUpTo(lo, patterns));
    uint64_t rightCount = (L == 0 ? 0 : countUpTo(L-1, patterns));
    if (leftCount - rightCount >= 1) return (int64_t)lo;
    return -1;
}

