Write a C++ function `nQueensSolutions(int n)` that returns all distinct solutions to the N-Queens puzzle for an `n x n` chessboard, where each solution is represented as a vector of integers of length `n`. The integer at position `i` (0-indexed) denotes the row number (1-indexed) where the queen is placed in column `i`. The function should return a vector of all such valid configurations, sorted in increasing lexicographic order of the integer sequences (as the natural order generated by scanning rows from top to bottom for each column). For example, for `n = 4`, there are two solutions: `{2, 4, 1, 3}` and `{3, 1, 4, 2}`. If no solution exists, return an empty vector. The function must handle `n` from 1 to 9 inclusively. The time complexity should be optimized with a backtracking approach that checks attack conditions efficiently.

#include <vector>
#include <string>

// Returns all distinct solutions to the N-Queens problem.
// Each solution is a vector of length n, where solution[col] gives the row (1-indexed) of the queen in that column.
// Solutions are returned in lexicographic order of the row sequences.
std::vector<std::vector<int>> nQueensSolutions(int n) {
    std::vector<std::vector<int>> solutions;
    std::vector<int> current(n, 0);          // current[col] = row (0-indexed during search)
    std::vector<bool> rowUsed(n, false);
    std::vector<bool> diag1Used(2 * n - 1, false); // main diagonal index = row - col + n - 1
    std::vector<bool> diag2Used(2 * n - 1, false); // anti-diagonal index = row + col

    // Backtracking helper.
    auto backtrack = [&](int col, auto&& self) -> void {
        if (col == n) {
            // Convert 0-indexed rows to 1-indexed and record.
            std::vector<int> sol;
            sol.reserve(n);
            for (int r : current) {
                sol.push_back(r + 1);
            }
            solutions.push_back(sol);
            return;
        }

        for (int row = 0; row < n; ++row) {
            int d1 = row - col + n - 1;
            int d2 = row + col;
            if (!rowUsed[row] && !diag1Used[d1] && !diag2Used[d2]) {
                current[col] = row;
                rowUsed[row] = true;
                diag1Used[d1] = true;
                diag2Used[d2] = true;

                self(col + 1, self);

                // Backtrack.
                rowUsed[row] = false;
                diag1Used[d1] = false;
                diag2Used[d2] = false;
            }
        }
    };

    backtrack(0, backtrack);
    return solutions;
}

